class EncapsulatedStudent { private String studentId; private String fullName; private int level; public EncapsulatedStudent(String id,String name,int level){setStudentId(id);setFullName(name);setLevel(level);} public String getStudentId(){return studentId;} public void setStudentId(String id){if(id==null||id.trim().isEmpty())throw new IllegalArgumentException("ID is required");studentId=id.trim();} public String getFullName(){return fullName;} public void setFullName(String name){if(name==null||name.trim().isEmpty())throw new IllegalArgumentException("Name is required");fullName=name.trim();} public int getLevel(){return level;} public void setLevel(int level){if(level!=100&&level!=200&&level!=300&&level!=400)throw new IllegalArgumentException("Level must be 100, 200, 300 or 400");this.level=level;} }
public class EncapsulatedStudentRecordDemo { public static void main(String[] args){EncapsulatedStudent s=new EncapsulatedStudent("ST002","Musa Bello",200);System.out.println(s.getStudentId()+" - "+s.getFullName()+" - "+s.getLevel()+" level");} }
